package br.com.admeclesial.infrastructure.persistence.projeto;
import br.com.admeclesial.domain.projeto.FonteRecursoProjeto; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.math.BigDecimal; import java.util.*;
public interface FonteRecursoProjetoRepository extends JpaRepository<FonteRecursoProjeto,Long>{ Optional<FonteRecursoProjeto> findByUuid(UUID uuid); List<FonteRecursoProjeto> findAllByProjetoIdOrderByIdAsc(Long projetoId); List<FonteRecursoProjeto> findAllByRecursoVinculadoIdOrderByIdAsc(Long recursoId); @Query("select coalesce(sum(f.valorAlocado),0) from FonteRecursoProjeto f where f.projetoId=:projetoId") BigDecimal sumValorAlocadoPorProjeto(@Param("projetoId") Long projetoId); @Query("select coalesce(sum(f.valorAlocado),0) from FonteRecursoProjeto f where f.recursoVinculadoId=:recursoId") BigDecimal sumValorAlocadoPorRecurso(@Param("recursoId") Long recursoId); }
